        const v29Tables=v29TableObjectProof(plan,expected,actual);if(!v29Tables.accepted)return reject(v29Tables.reason);
        const tableObjects=v272TableObjectProof(plan,expected,actual);if(!tableObjects.accepted)return reject(tableObjects.reason);
